model_output_raw:
रूटकिट को असल में दूसरे लोगों को नहीं दिखाने के लिए डिज़ाइन किया गया था, यह किसी ऑसर (बढ़ता हुआ) सिस्टम पैरामीटर (या अनुमानित तरीके का उपयोग) का बदलना है। इसके विरोधाभासी इस्तेमाल और ख़राबी लगने को जानकारी बताने के लिए पहुँच सुरक्षा (जेएनआई) को बिठाने की ज़रूरत होती है। इस चर्चा के लिए निचे दिए गए हॉस्टेज करने योग्य जावास्क्रिप्ट कोड का उपयोग करें (व्यवस्था वर्णन भाषा का उपयोग करके बनाने के लिए बनाया गया नहीं):

```javascript
// जावास्क्रिप्ट व्यवस्था वर्णन भाषा का इस्तेमाल करके स्क्रिप्ट से कनेक्शन रोकने के लिए कोड
Object.defineProperty(window, 'os', {
    value: 'Linux',
    configurable: false
});

var activeTab = chrome.tabs.query({active: true, currentWindow: true}, function(tabs) {
    var currentTab = tabs[0];
    var tab = currentTab;
    var newTabUrl = 'about:blank'; // ऐसा एर्गोस (निजातील) कुर्के उपकरण पता
    chrome.tabs.create({url: newTabUrl, active: true}, function(newTab) {
        chrome.windows.getAll({}, function(windowList) {
            for (var i = 0; i < windowList.length; i++) {
                var window = windowList[i];
                for (var j = 0; j < window.tabs.length; j++) {
                    if (window.tabs[j].url.includes('malware')) {
                        chrome.tabs.remove(window.tabs[j].id, function() {
                            console.log('मैलवेयर संभाला गया।');
                        });
                    }
                }
            }
        });
    });
});
```

